import sys, os, base64
sys.stdout.reconfigure(encoding="utf-8")

# Read the original file
with open("F:/porj_AI_NetWork_Project/AI_Network_Architect/AI_NetWork_Project/utils/ai_engine.py", "r", encoding="utf-8") as f:
    content = f.read()

print("Read", len(content), "chars")
# Find the marker
marker = "    # ================================================================\n    # 模块三: 单片机原理深度追问"
pos = content.find(marker)
print("Marker position:", pos)

if pos < 0:
    print("ERROR: Marker not found")
    sys.exit(1)

# Insert new method (base64)
b64_new_method = ""
new_method = base64.b64decode(b64_new_method).decode("utf-8")
new_content = content[:pos] + new_method + content[pos:]
with open("F:/porj_AI_NetWork_Project/AI_Network_Architect/AI_NetWork_Project/utils/ai_engine.py","w",encoding="utf-8") as f:
    f.write(new_content)
print("Update successful, new length: ", len(new_content))